<?php
use App\Models\Customer;use App\Support\CurrentCompany;use Livewire\Attributes\Title;use Livewire\Component;use Livewire\WithPagination;
new #[Title('Customers')] class extends Component {use WithPagination;public string $search='';public function updatedSearch():void{$this->resetPage();}public function with(CurrentCompany $current):array{$term='%'.$this->search.'%';return ['customers'=>Customer::where('company_id',$current->id(auth()->user()))->when($this->search!=='',fn($q)=>$q->where(fn($q)=>$q->where('name','like',$term)->orWhere('trading_name','like',$term)->orWhere('account_number','like',$term)))->orderBy('name')->paginate(10)];}};?>
<section class="w-full p-6"><flux:heading size="xl">Customers</flux:heading><x-pages::shared.layout contentclass="max-w-7xl"><div class="mb-4 flex justify-between"><flux:input class="max-w-sm" wire:model.live.debounce.300ms="search" icon="magnifying-glass" placeholder="Search customers..."/>@can('crm.customer.create')<flux:button variant="primary" :href="route('crm.customers.create')">Add Customer</flux:button>@endcan</div><flux:table :paginate="$customers"><flux:table.columns><flux:table.column>Iteration</flux:table.column><flux:table.column>Account number</flux:table.column><flux:table.column>Name / trading name</flux:table.column><flux:table.column align="end">Actions</flux:table.column></flux:table.columns><flux:table.rows>@forelse($customers as $customer)<flux:table.row :key="$customer->id"><flux:table.cell>{{ $customers->firstItem()+$loop->index }}</flux:table.cell><flux:table.cell>{{ $customer->account_number }}</flux:table.cell><flux:table.cell><strong>{{ $customer->name }}</strong>@if($customer->trading_name)<br><span class="text-xs text-zinc-500">{{ $customer->trading_name }}</span>@endif</flux:table.cell><flux:table.cell align="end"><flux:dropdown><flux:button size="sm" variant="ghost" icon="ellipsis-horizontal"/><flux:menu><flux:menu.item icon="pencil" :href="route('crm.customers.update',$customer)">Manage</flux:menu.item><flux:menu.item icon="wrench-screwdriver" :href="route('crm.customers.update',$customer).'?tab=equipment'">Equipment</flux:menu.item><flux:menu.item icon="truck" :href="route('crm.customers.update',$customer).'?tab=movements'">Movements</flux:menu.item></flux:menu></flux:dropdown></flux:table.cell></flux:table.row>@empty<flux:table.row><flux:table.cell colspan="4">No customers found</flux:table.cell></flux:table.row>@endforelse</flux:table.rows></flux:table></x-pages::shared.layout></section>
